import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useModal } from '../context/ModalContext';

const Auth = ({ isLogin = true }) => {
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    rememberMe: false,
  });
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const { login, register, user } = useAuth();
  const { showModal } = useModal();
  const navigate = useNavigate();

  // Если пользователь уже авторизован, перенаправляем в профиль
  React.useEffect(() => {
    if (user) {
      navigate('/profile');
    }
  }, [user, navigate]);

  const validateForm = () => {
    const newErrors = {};

    if (!formData.email) {
      newErrors.email = 'Email обязателен';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Некорректный email';
    }

    if (!formData.password) {
      newErrors.password = 'Пароль обязателен';
    } else if (formData.password.length < 6) {
      newErrors.password = 'Пароль должен быть не менее 6 символов';
    }

    if (!isLogin) {
      if (!formData.username) {
        newErrors.username = 'Имя пользователя обязательно';
      } else if (formData.username.length < 3) {
        newErrors.username = 'Имя должно быть не менее 3 символов';
      }

      if (formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = 'Пароли не совпадают';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setLoading(true);

    try {
      if (isLogin) {
        await login(formData.email, formData.password);
        showModal('success', null, 'Вход выполнен успешно!', 'Добро пожаловать обратно!');
      } else {
        await register(formData.username, formData.email, formData.password);
        showModal('success', null, 'Регистрация успешна!', 'Добро пожаловать в Luxury Brands!');
      }

      // Перенаправляем в профиль
      navigate('/profile');

    } catch (error) {
      console.error('Auth error:', error);
      showModal('error', null, 'Ошибка', error.message || 'Что-то пошло не так');
    } finally {
      setLoading(false);
    }
  };

  const switchMode = () => {
    setFormData({
      username: '',
      email: '',
      password: '',
      confirmPassword: '',
      rememberMe: false,
    });
    setErrors({});
    navigate(isLogin ? '/register' : '/login');
  };

  return (
    <div className="max-w-md mx-auto mt-8 p-6 bg-white rounded-lg shadow-lg">
      <h2 className="text-2xl font-serif font-bold text-center mb-6">
        {isLogin ? 'Вход в аккаунт' : 'Регистрация'}
      </h2>

      <form onSubmit={handleSubmit} className="space-y-4">
        {!isLogin && (
          <div>
            <label className="block text-sm font-medium mb-1">Имя пользователя *</label>
            <input
              type="text"
              value={formData.username}
              onChange={(e) => setFormData({...formData, username: e.target.value})}
              className={`w-full px-3 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-gold-500 ${
                errors.username ? 'border-red-500' : 'border-gray-300'
              }`}
              placeholder="Введите ваше имя"
              disabled={loading}
            />
            {errors.username && (
              <p className="text-red-500 text-sm mt-1">{errors.username}</p>
            )}
          </div>
        )}

        <div>
          <label className="block text-sm font-medium mb-1">Email *</label>
          <input
            type="email"
            value={formData.email}
            onChange={(e) => setFormData({...formData, email: e.target.value})}
            className={`w-full px-3 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-gold-500 ${
              errors.email ? 'border-red-500' : 'border-gray-300'
            }`}
            placeholder="example@mail.com"
            disabled={loading}
          />
          {errors.email && (
            <p className="text-red-500 text-sm mt-1">{errors.email}</p>
          )}
        </div>

        <div>
          <label className="block text-sm font-medium mb-1">Пароль *</label>
          <input
            type="password"
            value={formData.password}
            onChange={(e) => setFormData({...formData, password: e.target.value})}
            className={`w-full px-3 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-gold-500 ${
              errors.password ? 'border-red-500' : 'border-gray-300'
            }`}
            placeholder="Не менее 6 символов"
            minLength="6"
            disabled={loading}
          />
          {errors.password && (
            <p className="text-red-500 text-sm mt-1">{errors.password}</p>
          )}
        </div>

        {!isLogin && (
          <div>
            <label className="block text-sm font-medium mb-1">Подтвердите пароль *</label>
            <input
              type="password"
              value={formData.confirmPassword}
              onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})}
              className={`w-full px-3 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-gold-500 ${
                errors.confirmPassword ? 'border-red-500' : 'border-gray-300'
              }`}
              placeholder="Повторите пароль"
              minLength="6"
              disabled={loading}
            />
            {errors.confirmPassword && (
              <p className="text-red-500 text-sm mt-1">{errors.confirmPassword}</p>
            )}
          </div>
        )}

        {isLogin && (
          <div className="flex items-center">
            <input
              type="checkbox"
              id="rememberMe"
              checked={formData.rememberMe}
              onChange={(e) => setFormData({...formData, rememberMe: e.target.checked})}
              className="h-4 w-4 text-gold-600 focus:ring-gold-500 border-gray-300 rounded"
              disabled={loading}
            />
            <label htmlFor="rememberMe" className="ml-2 block text-sm text-gray-900">
              Запомнить меня
            </label>
          </div>
        )}

        <button
          type="submit"
          disabled={loading}
          className={`w-full bg-gold-600 hover:bg-gold-700 text-white py-3 rounded font-semibold transition-colors ${
            loading ? 'opacity-70 cursor-not-allowed' : ''
          }`}
        >
          {loading ? (
            <div className="flex items-center justify-center">
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
              {isLogin ? 'Вход...' : 'Регистрация...'}
            </div>
          ) : isLogin ? 'Войти' : 'Зарегистрироваться'}
        </button>
      </form>

      <div className="mt-6 text-center">
        <button
          type="button"
          onClick={switchMode}
          className="text-gold-600 hover:text-gold-700 font-medium"
          disabled={loading}
        >
          {isLogin ? 'Нет аккаунта? Зарегистрироваться' : 'Уже есть аккаунт? Войти'}
        </button>
      </div>

      {/* Демо данные для тестирования */}
      {isLogin && (
        <div className="mt-6 p-4 bg-gray-50 rounded-lg">
          <h3 className="text-sm font-semibold mb-2">Для тестирования:</h3>
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div>
              <p className="font-medium">Email:</p>
              <p className="text-gray-600">test@example.com</p>
            </div>
            <div>
              <p className="font-medium">Пароль:</p>
              <p className="text-gray-600">123456</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Auth;
